Looking at the `parseContent` function, the issue is that when we're inside a code block, we should ignore any nested ` ``` ` markers and treat them as content lines.

The fix is to track when we're "inside" a block (between opening and closing fences) and only process fence markers when we're at the top level.

```vue src/components/document/Document.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue';
import Code from '../Code.vue';
import HTMLViewer from '../HTMLViewer.vue';
</script>

<template>
  <div class="flex flex-col @container/document">
    <div v-for="block in blocks" :key="block.hash">
      <MarkdownViewer
        :files="files"
        v-if="block.renderer === 'md'"
        :text="block.content"
      />
      <Code
        :class="!block.finished && 'border border-dashed border-slate-400'"
        :text="block.content"
        :text-language="block.type"
        :fileName="block.fileName"
        :files="files"
        :project="docProject"
        :finished="block.finished"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', { file: $event, message })"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @add-file="$emit('add-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        v-else
      />
      <div class="chat-footer opacity-50 text-xs font-bold" v-if="!block.finished">
        loading <span class="loading loading-spinner"></span>
      </div>
    </div>
  </div>
</template>

<script>
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

function getRenderer(blockType) {
  if (['markdown', 'md'].includes(blockType)) return 'md'
  if (['html'].includes(blockType)) return blockType
  return 'code'
}

function parseContent(content) {
  const blocks = []
  const lines = content.split('\n')
  let currentType = 'markdown'
  let currentContent = []
  let currentFileName = ''
  // Track if we're inside a typed code block (e.g. ```js ...)
  let insideBlock = false

  function setAllFinished() {
    blocks.forEach(b => b.finished = true)
  }

  function addBlock() {
    const blockContent = currentContent.join('\n')
    const hash = generateHash(blockContent)
    setAllFinished()
    blocks.push({
      type: currentType,
      content: blockContent,
      hash,
      fileName: currentFileName,
      renderer: getRenderer(currentType),
      finished: false
    })
    // Reset state
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
  }

  for (const line of lines) {
    const openMatch = line.trim().match(/^```(\w+)\s*(.*)$/)
    const closeMatch = line.trim() === '```'

    if (!insideBlock && openMatch) {
      // Opening a new typed block — flush any markdown content first
      if (currentContent.length) {
        addBlock()
      }
      insideBlock = true
      currentType = openMatch[1]
      currentFileName = openMatch[2] || ''
    } else if (insideBlock && closeMatch) {
      // Closing the current typed block
      addBlock()
      insideBlock = false
    } else {
      // Inside a block: add line as-is (nested ``` markers are treated as content)
      // Outside a block: accumulate markdown content
      currentContent.push(line)
    }
  }

  // Flush any remaining content
  if (currentContent.length) {
    addBlock()
  }

  setAllFinished()
  return blocks
}

export default {
  props: ['content', 'files', 'project'],
  computed: {
    blocks() {
      return parseContent(this.content || '')
    },
    docProject() {
      return this.project || this.$project
    },
  },
}
</script>
```

### Key changes in `parseContent`:

1. **Replaced `fenceCount` with a simple `insideBlock` boolean** — we only need to know if we're at the top level or inside a typed block, no need to count nesting levels.

2. **When `insideBlock` is `true`**, any line (including lines matching ` ```lang ` or plain ` ``` `) is pushed directly to `currentContent` as raw content, effectively ignoring nested fence markers.

3. **Opening a block** (```` ```lang ```` pattern) is only recognized when `insideBlock === false`.

4. **Closing a block** (plain ` ``` `) is only recognized when `insideBlock === true`.

Looking at the parsing logic, the issue is that when `insideBlock` is true and we encounter another opening ` ``` ` pattern, it should be treated as content, not as a new block opener. The current code handles the close match but not nested opens properly.

```vue src/components/document/Document.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue';
import Code from '../Code.vue';
import HTMLViewer from '../HTMLViewer.vue';
</script>

<template>
  <div class="flex flex-col @container/document">
    <div v-for="block in blocks" :key="block.hash">
      <MarkdownViewer
        :files="files"
        v-if="block.renderer === 'md'"
        :text="block.content"
      />
      <Code
        :class="!block.finished && 'border border-dashed border-slate-400'"
        :text="block.content"
        :text-language="block.type"
        :fileName="block.fileName"
        :files="files"
        :project="docProject"
        :finished="block.finished"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', { file: $event, message })"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @add-file="$emit('add-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        v-else
      />
      <div class="chat-footer opacity-50 text-xs font-bold" v-if="!block.finished">
        loading <span class="loading loading-spinner"></span>
      </div>
    </div>
  </div>
</template>

<script>
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

function getRenderer(blockType) {
  if (['markdown', 'md'].includes(blockType)) return 'md'
  if (['html'].includes(blockType)) return blockType
  return 'code'
}

function parseContent(content) {
  const blocks = []
  const lines = content.split('\n')
  let currentType = 'markdown'
  let currentContent = []
  let currentFileName = ''
  // Track nesting depth: 0 = markdown level, 1+ = inside typed block(s)
  let nestingDepth = 0

  function setAllFinished() {
    blocks.forEach(b => b.finished = true)
  }

  function addBlock() {
    const blockContent = currentContent.join('\n')
    const hash = generateHash(blockContent)
    setAllFinished()
    blocks.push({
      type: currentType,
      content: blockContent,
      hash,
      fileName: currentFileName,
      renderer: getRenderer(currentType),
      finished: false
    })
    // Reset state
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
  }

  for (const line of lines) {
    const trimmed = line.trim()
    const openMatch = trimmed.match(/^```(\w+)\s*(.*)$/)
    const closeMatch = trimmed === '```'

    if (nestingDepth === 0 && openMatch) {
      // At top level: opening a new typed block — flush any markdown content first
      if (currentContent.length) {
        addBlock()
      }
      nestingDepth = 1
      currentType = openMatch[1]
      currentFileName = openMatch[2] || ''
    } else if (nestingDepth === 1 && closeMatch) {
      // Closing the top-level typed block
      addBlock()
      nestingDepth = 0
    } else if (nestingDepth >= 1 && openMatch) {
      // Nested opening inside a typed block — treat as content, increase depth
      nestingDepth++
      currentContent.push(line)
    } else if (nestingDepth > 1 && closeMatch) {
      // Closing a nested block — treat as content, decrease depth
      nestingDepth--
      currentContent.push(line)
    } else {
      // Regular content line at any level
      currentContent.push(line)
    }
  }

  // Flush any remaining content
  if (currentContent.length) {
    addBlock()
  }

  setAllFinished()
  return blocks
}

export default {
  props: ['content', 'files', 'project'],
  computed: {
    blocks() {
      return parseContent(this.content || '')
    },
    docProject() {
      return this.project || this.$project
    },
  },
}
</script>
```

Key changes in the parsing logic:

- **Replaced `insideBlock` boolean** with `nestingDepth` integer to track nesting levels
- **`nestingDepth === 0`**: top-level markdown, an open match starts a new typed block
- **`nestingDepth === 1` + close**: closes the top-level block properly
- **`nestingDepth >= 1` + open**: nested open → pushed as content, depth increases
- **`nestingDepth > 1` + close**: nested close → pushed as content, depth decreases

This ensures nested ` ``` ` markers inside a parent block are treated as plain content lines.
